python3 - <<'PY'
import csv
from decimal import Decimal

def read(path):
    with open(path,newline='') as f:
        return list(csv.DictReader(f))

def dec(x):
    return Decimal(str(x))

def sums(rows,prefix):
    out={}
    for m in ['jan','feb','mar','apr']:
        out[m]=sum(dec(r[f'{m}_{prefix}']) for r in rows)
    return out

bus=read('/root/bus_pass_schedule_input.csv')
rail=read('/root/rail_pass_schedule_input.csv')
for name,rows in [('bus',bus),('rail',rail)]:
    print(name,'rowcount',len(rows))
    print('beginning_balance sum',sum(dec(r['beginning_balance']) for r in rows))
    print('ending_balance sums',sums(rows,'ending_balance'))
    print('adds sums',sums(rows,'adds'))
    print('amortization sums',sums(rows,'amortization'))
    print('account_numbers',sorted({r['account_number'] for r in rows}))
    print()
